import { create } from "zustand";
import { v4 as uuidv4 } from "uuid";
import { toast } from "sonner";

export interface Message {
  id: string;
  role: "user" | "assistant";
  content: string;
  timestamp: Date;
  total_tokens?: number;
}

export interface ChatItem {
  id: string;
  title: string;
  messages: Message[];
  total_tokens: number;
  createdAt: Date;
  updatedAt: Date;
}

interface ChatStore {
  chats: ChatItem[];
  setChats: (chats: ChatItem[]) => void;
  // createChat, deleteChat, fetchChats removed in favor of React Query
  updateChat: (id: string, title: string) => void;
  getChatById: (id: string) => ChatItem | undefined;
  addMessage: (chatId: string, role: "user" | "assistant", content: string) => Promise<void>;
  isLoading: boolean;
}

export const useChatStore = create<ChatStore>((set, get) => ({
  chats: [],
  isLoading: false, // Managed by Query generally, but kept for addMessage streaming state if needed

  setChats: (chats: ChatItem[]) => set({ chats }),

  updateChat: (id: string, title: string) => {
    set((state) => ({
      chats: state.chats.map((chat) =>
        chat.id === id ? { ...chat, title, updatedAt: new Date() } : chat
      ),
    }));
  },

  // TODO: Refactor addMessage to useMutation. 
  // currently it updates the store manually which might be out of sync with Query cache 
  // unless we invalidate or setQueryData.
  // For now, components using useGetChat should rely on *store updates* for streaming content
  // if we sync the store with Query data on load.
  addMessage: async (chatId: string, role: "user" | "assistant", content: string) => {
    // ... (keep existing complex streaming logic for now)
    // We will need to sync this back to React Query cache or just invalidate on finish.
    // Copy pasting the existing logic but removing the fetchChats call at the end.

    const newMessage: Message = {
      id: uuidv4(),
      role,
      content,
      timestamp: new Date(),
    };

    set((state) => ({
      chats: state.chats.map((chat) =>
        chat.id === chatId
          ? {
            ...chat,
            messages: [...chat.messages, newMessage],
            updatedAt: new Date(),
          }
          : chat
      ),
    }));

    if (role === "user") {
      const activeChat = get().chats.find(c => c.id === chatId);
      if (!activeChat) return;

      try {
        const response = await fetch("http://localhost:8000/api/chat/stream", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            prompt: content,
            chat_id: chatId,
            model: "gpt-5-mini"
          }),
        });

        if (!response.ok) {
          const errorData = await response.json().catch(() => ({ detail: "Unknown server error" }));
          throw new Error(errorData.detail || "Failed to connect to AI server");
        }

        const reader = response.body?.getReader();
        if (!reader) return;

        const assistantMessageId = uuidv4();
        let assistantContent = "";

        set((state) => ({
          chats: state.chats.map((chat) =>
            chat.id === chatId
              ? {
                ...chat,
                messages: [
                  ...chat.messages,
                  { id: assistantMessageId, role: "assistant", content: "", timestamp: new Date() }
                ],
              }
              : chat
          ),
        }));

        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          const chunk = new TextDecoder().decode(value);

          if (chunk.includes("🚨 Error:")) {
            toast.error(chunk.replace("🚨", "").trim());
          }

          assistantContent += chunk;

          set((state) => ({
            chats: state.chats.map((chat) =>
              chat.id === chatId
                ? {
                  ...chat,
                  messages: chat.messages.map(m =>
                    m.id === assistantMessageId ? { ...m, content: assistantContent } : m
                  ),
                }
                : chat
            ),
          }));
        }

        // Removed fetchChats() here. 
        // Ideally invalidation should happen here via a callback or event.

      } catch (error: any) {
        console.error("Streaming error:", error);
        toast.error(error.message || "Unable to reach the AI server.");

        set((state) => ({
          chats: state.chats.map((chat) =>
            chat.id === chatId
              ? {
                ...chat,
                messages: [
                  ...chat.messages,
                  { id: uuidv4(), role: "assistant", content: `🚨 ${error.message || "Unable to reach the AI server."}`, timestamp: new Date() }
                ],
              }
              : chat
          ),
        }));
      }
    }
  },
  getChatById: (id: string) => {
    return get().chats.find((chat) => chat.id === id);
  },
}));
